#!/usr/bin/env python3
"""
Minimal agentic loop using Anthropic API with bash tool and human confirmation.
"""

import os
import sys
import subprocess
import json
from typing import Dict, List, Optional
import anthropic

class BashTool:
    """Tool for executing bash commands with user confirmation."""

    @staticmethod
    def execute(command: str) -> Dict[str, any]:
        """Execute a bash command after user confirmation."""
        print(f"\n🔧 Tool Request: Run Bash Command")
        print(f"Command: {command}")
        print("-" * 50)

        confirmation = input("Execute this command? (y/n): ").strip().lower()
        if confirmation != 'y':
            return {
                "success": False,
                "output": "Command execution cancelled by user.",
                "error": None
            }

        try:
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30
            )
            return {
                "success": True,
                "output": result.stdout,
                "error": result.stderr if result.stderr else None,
                "return_code": result.returncode
            }
        except subprocess.TimeoutExpired:
            return {
                "success": False,
                "output": None,
                "error": "Command timed out after 30 seconds"
            }
        except Exception as e:
            return {
                "success": False,
                "output": None,
                "error": str(e)
            }

class AgentLoop:
    """Minimal agentic loop with Anthropic API."""

    def __init__(self, api_key: Optional[str] = None):
        """Initialize the agent with API key."""
        self.api_key = api_key or os.environ.get("ANTHROPIC_API_KEY")
        if not self.api_key:
            raise ValueError("ANTHROPIC_API_KEY environment variable not set")

        self.client = anthropic.Anthropic(api_key=self.api_key)
        self.messages = []
        self.bash_tool = BashTool()

        # Tool definition for Claude
        self.tools = [{
            "name": "run_bash",
            "description": "Execute a bash command",
            "input_schema": {
                "type": "object",
                "properties": {
                    "command": {
                        "type": "string",
                        "description": "The bash command to execute"
                    }
                },
                "required": ["command"]
            }
        }]

    def process_tool_use(self, tool_use: Dict) -> Dict[str, any]:
        """Process a tool use request from Claude."""
        if tool_use["name"] == "run_bash":
            command = tool_use["input"]["command"]
            return self.bash_tool.execute(command)
        else:
            return {
                "success": False,
                "output": f"Unknown tool: {tool_use['name']}",
                "error": None
            }

    def run(self):
        """Run the main agent loop."""
        print("🤖 Agent Loop Started")
        print("Type 'exit' or 'quit' to stop")
        print("-" * 50)

        while True:
            # Get user input
            user_input = input("\n👤 You: ").strip()
            if user_input.lower() in ['exit', 'quit']:
                print("👋 Goodbye!")
                break

            if not user_input:
                continue

            # Add user message
            self.messages.append({
                "role": "user",
                "content": user_input
            })

            try:
                # Get Claude's response
                response = self.client.messages.create(
                    model="claude-3-5-sonnet-20241022",
                    max_tokens=4096,
                    messages=self.messages,
                    tools=self.tools
                )

                # Process the response
                assistant_message = {
                    "role": "assistant",
                    "content": []
                }

                for content_block in response.content:
                    if content_block.type == "text":
                        print(f"\n🤖 Assistant: {content_block.text}")
                        assistant_message["content"].append({
                            "type": "text",
                            "text": content_block.text
                        })

                    elif content_block.type == "tool_use":
                        # Execute the tool
                        tool_result = self.process_tool_use(content_block)

                        # Add tool use to assistant message
                        assistant_message["content"].append({
                            "type": "tool_use",
                            "id": content_block.id,
                            "name": content_block.name,
                            "input": content_block.input
                        })

                        # Add tool result
                        self.messages.append(assistant_message)

                        # Format tool result for display
                        print(f"\n📊 Tool Result:")
                        if tool_result["success"]:
                            if tool_result["output"]:
                                print(f"Output:\n{tool_result['output']}")
                            if tool_result.get("error"):
                                print(f"Stderr:\n{tool_result['error']}")
                        else:
                            print(f"Error: {tool_result['error'] or tool_result['output']}")

                        # Add tool result message
                        self.messages.append({
                            "role": "user",
                            "content": [{
                                "type": "tool_result",
                                "tool_use_id": content_block.id,
                                "content": json.dumps(tool_result)
                            }]
                        })

                        # Get Claude's response after tool execution
                        followup = self.client.messages.create(
                            model="claude-3-5-sonnet-20241022",
                            max_tokens=4096,
                            messages=self.messages,
                            tools=self.tools
                        )

                        # Process followup
                        followup_content = []
                        for block in followup.content:
                            if block.type == "text":
                                print(f"\n🤖 Assistant: {block.text}")
                                followup_content.append({
                                    "type": "text",
                                    "text": block.text
                                })

                        if followup_content:
                            self.messages.append({
                                "role": "assistant",
                                "content": followup_content
                            })

                        # Skip adding the original assistant message since we handled it
                        continue

                # Add assistant message if no tools were used
                if assistant_message["content"] and not any(
                    c.get("type") == "tool_use" for c in assistant_message["content"]
                ):
                    self.messages.append(assistant_message)

            except anthropic.APIError as e:
                print(f"\n❌ API Error: {e}")
            except Exception as e:
                print(f"\n❌ Error: {e}")

def main():
    """Main entry point."""
    try:
        agent = AgentLoop()
        agent.run()
    except ValueError as e:
        print(f"❌ {e}")
        print("Please set the ANTHROPIC_API_KEY environment variable")
        sys.exit(1)
    except KeyboardInterrupt:
        print("\n\n👋 Goodbye!")
        sys.exit(0)

if __name__ == "__main__":
    main()

